def next_bus(times: list[str], now: str) -> str:
    # 時刻文字列を分単位に変換して比較しやすくする
    def to_minutes(time_str: str) -> int:
        h, m = map(int, time_str.split(':'))
        return h * 60 + m

    # 全ての時刻を分単位に変換
    now_minutes = to_minutes(now)
    times_minutes = [to_minutes(t) for t in times]

    # 今日中の便（now以降）を探す
    for t in times_minutes:
        if t >= now_minutes:
            # 元の文字列形式に戻す
            for time_str in times:
                if to_minutes(time_str) == t:
                    return time_str

    # 今日中に便がなければ、明日の最初の便（最も早い時刻）
    min_time = min(times_minutes)
    for time_str in times:
        if to_minutes(time_str) == min_time:
            return time_str
```

